entries[18454] = { ["name"] = "Gloves of Spell Mastery", ["text"] = "2 sec cast\nReagents:\nBolt of Runecloth (10), Mooncloth (10), Ghost Dye (10), Golden Pearl (6), Huge Emerald (6), Enchanted Leather (8), Rune Thread (2)\nDrop:\nWorld Creatures\n\nGloves of Spell Mastery\nBinds when equipped\nHands Cloth\n2 Armor\n+2 Intellect\n+ 6 Critical Strike\n+ 2 Versatility\nDurability 55 / 55\nClasses: Priest , Mage , Warlock\n24" }
entries[18455] = { ["name"] = "Bottomless Bag", ["text"] = "2.5 sec cast\nReagents:\nBolt of Runecloth (8), Mooncloth (12), Large Brilliant Shard (2), Core Leather (2), Rune Thread (2)\nDrop:\nWorld Creatures\n\nBottomless Bag\nBinds when equipped\n18 Slot Bag" }
entries[18456] = { ["name"] = "Truefaith Vestments", ["text"] = "2 sec cast\nReagents:\nBolt of Runecloth (12), Mooncloth (10), Righteous Orb (4), Golden Pearl (4), Ghost Dye (10), Rune Thread (2)\nDrop:\nBalnazzar\nZone:\nStratholme\n\nTruefaith Vestments\nBinds when picked up\nChest Cloth\n4 Armor\n+5 Intellect\n+5 Stamina\n+ 4 Versatility\nDurability 165 / 165\nClasses: Priest\nEquip: Reduces the cooldown of your Fade ability by 2 sec.\n24" }
entries[18457] = { ["name"] = "Robe of the Archmage", ["text"] = "2 sec cast\nReagents:\nBolt of Runecloth (12), Essence of Fire (10), Essence of Air (10), Essence of Earth (10), Essence of Water (10), Rune Thread (2)\nDrop:\nFirebrand Pyromancer\nZone:\nBlackrock Spire\n\nRobe of the Archmage\nBinds when picked up\nChest Cloth\n4 Armor\n+5 Intellect\n+5 Stamina\n+ 3 Critical Strike\nDurability 165 / 165\nUse: Restores 95 mana. (5 Min Cooldown)\n24" }
entries[18458] = { ["name"] = "Robe of the Void", ["text"] = "2 sec cast\nReagents:\nBolt of Runecloth (12), Demonic Rune (20), Felcloth (40), Essence of Fire (12), Essence of Undeath (12), Rune Thread (2)\nDrop:\nDarkmaster Gandling\nZone:\nScholomance\n\nRobe of the Void\nBinds when picked up\nChest Cloth\n4 Armor\n+6 Intellect\n+5 Stamina\nDurability 165 / 165\nUse: Heal your pet for 10 . (10 Min Cooldown)\n24" }
entries[18476] = { ["name"] = "Summon Minion" }
entries[18499] = { ["name"] = "Berserker Rage", ["text"] = "Instant 1 min cooldown\nGo berserk, removing and granting immunity to Fear, Sap, and some Incapacitate effects for 6 sec." }
entries[18500] = { ["name"] = "Wing Buffet", ["text"] = "0.5 sec cast\nInflicts 5594 damage to enemies in a cone in front of the caster, knocking them back. This effect ignores armor." }
entries[18501] = { ["name"] = "Enrage", ["text"] = "Instant\nIncreases the Physical damage dealt by the caster and speeds its attacks for 5 sec." }
entries[18502] = { ["name"] = "Curse of Hakkar", ["text"] = "200 Mana 30 yd range\n2.5 sec cast\nDrains 5 mana from an enemy every 5 sec., transferring it to the caster over 2 min." }
entries[18503] = { ["name"] = "Hex", ["text"] = "20 Mana 20 yd range\nInstant\nTransforms an enemy into a chicken, rendering it unable to attack or cast spells for 5 sec." }
entries[18540] = { ["name"] = "Summon Doomguard", ["text"] = "1 Soul Shard 40 yd range\nInstant\nSummons a Doomguard for 15 min to assault the target with its Doom Bolts." }
entries[18542] = { ["name"] = "Immolate", ["text"] = "(Proc chance: 10%)" }
entries[18543] = { ["name"] = "Flame Lash", ["text"] = "30 yd range\nInstant\nBurns an enemy, then inflicts additional Fire damage every 3 sec. for 15 sec." }
entries[18545] = { ["name"] = "Scorpid Sting", ["text"] = "10 Mana 5 - 30 yd range\nRequires Ranged Weapon\nStings an enemy, reducing its Strength and Agility by 1 for 20 sec." }
entries[18546] = { ["name"] = "Overdrive", ["text"] = "Instant\nImmobilizes the caster, but increases its attack speed by 100% for 6 sec." }
entries[18557] = { ["name"] = "Drain Life", ["text"] = "75 Mana 20 yd range\nChanneled (5 sec cast)\nDrains 20 health from an enemy over 5 sec., transferring it to the caster." }
entries[18559] = { ["name"] = "Demon Pick", ["text"] = "5 yd range\n5 sec cast\nDemon Pick to Destroy Demon Crystal." }
entries[18560] = { ["name"] = "Mooncloth", ["text"] = "1.5 sec cast\nReagents:\nFelcloth (2)\nThe purification of tainted Felcloth into Mooncloth can only be done at a moonwell, and only occasionally will the waters permit themselves to be used in such a way.\nVendor:\nQia\nZone:\nWinterspring\nCost:\n2\n\nCrafting Reagent" }
entries[18561] = { ["name"] = "Shoot", ["text"] = "5 - 30 yd range\nInstant\nRequires Ranged Weapon\nShoots at an enemy, inflicting Physical damage." }
entries[18562] = { ["name"] = "Swiftmend", ["text"] = "10% of base mana 40 yd range\nInstant 15 sec cooldown\n1 Charge\nConsumes a Regrowth, Wild Growth, or Rejuvenation effect to instantly heal an ally for (772.8% of Spell Power)." }
